/// <summary>
///    AVA <c>AVACheckTitleIdTxt</c> method.
/// </summary>
public void AVACheckAVATitleIdTxt()
{
    if(this.TitleId != '')
    {
        this.AVATitleIdTxt = this.TitleId;
    }
}

/// <summary>
///    AVA <c>update</c> method.
/// </summary>
public void update()
{
    this.AVACheckAVATitleIdTxt();

    next update();
}

/// <summary>
///    AVA <c>insert</c> method.
/// </summary>
public void insert()
{
    this.AVACheckAVATitleIdTxt();

    next insert();
}

/// <summary>
///    AVA <c>getTitleIdTranslation</c> method.
/// </summary>
/// <param name="_languageId">
///    <c>LanguageId</c> as type
/// </param>
/// <returns>
///    <c>smmContactPrivateTitle</c> as return value
/// </returns>
public smmContactPrivateTitle getTitleIdTranslation(LanguageId _languageId = CompanyInfo::languageId())
{
    smmContactPrivateTitle retVal;

    //smmContactTitleGroup                locsmmContactTitleGroup;
    AVAsmmContactTitleGroupTranslation  locAVAsmmContactTitleGroupTranslation;

    retVal = this.TitleId;

    locAVAsmmContactTitleGroupTranslation = AVAsmmContactTitleGroupTranslation::findBysmmContactTitleGroupAndLanguage(this.RecId, _languageId);
    if(     locAVAsmmContactTitleGroupTranslation.RecId
        &&  locAVAsmmContactTitleGroupTranslation.AVATitleIdTxt)
    {
        retVal = locAVAsmmContactTitleGroupTranslation.AVATitleIdTxt;
    }

    return retVal;
}
